import {days,weekLabel,intersects,slotBundle} from './engine.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(a,t,c='')=>`<button data-action="${a}" class="${c}">${t}</button>`;
export function assignmentText(p,a){return `${p.groups.find(g=>g.id===a.group)?.code||'?'} · ${a.sub} п/г · ${days[a.day]} ${a.pair} · ${weekLabel(a.week)} · ${p.teachers.find(t=>t.id===a.teacher)?.name||'?'}`}
const metric=m=>`окон (пустых пар): ${m.gaps}; приездов за I+II недели: ${m.visits}; коротких дней (1–2 пары): ${m.shortDays}; максимум дней/нед.: ${m.maxDays}; закрытых пар I/II: ${m.pairedAlternating}; незакрытых мигалок: ${m.unpairedAlternating}`;
export function plannerView(p,w){if(!w)return '';return `<div class="modal-shade"><section class="planner-dialog" role="dialog" aria-modal="true" aria-label="Мастер расстановки"><h2>Мастер расстановки</h2>${w.busy?'<p id="planner-progress" role="status">Подготавливаю данные…</p><p>Можно отменить расчёт.</p>':w.result?`${w.result.mode==='compact'?'<p>Уплотнение готового расписания без изменения дней и пар.</p>':`<p>Обработано задач: ${w.result.processed} из ${w.result.total}.</p>`}<p>Новых назначений: ${w.result.added.length}; изменено: ${w.result.changed.length}; возвращено в очередь: ${w.result.removed.length}.</p><p>До: ${metric(w.result.before)}</p><p>После: ${metric(w.result.after)}</p>${w.result.timedOut?'<p class="warning">Лимит поиска достигнут. Можно применить частичный результат и запустить «Дополнить» ещё раз либо увеличить время поиска.</p>':''}<p>Уплотнение: перемещено назначений ${w.result.compaction?.moves||0}; сокращение числа приездов за I+II недели ${w.result.compaction?.freedVisits||0}.</p><h3>Новые и изменённые назначения</h3>${w.result.added.concat(w.result.changed).map(a=>`<p>${esc(assignmentText(p,a))}${!a.room?' · <b>Требуется аудитория</b>':''}</p>`).join('')||'<p>Нет изменений.</p>'}<h3>Не распределено</h3>${w.result.unresolved.map(x=>`<p class="warning">${esc(p.groups.find(g=>g.id===x.group)?.code)}${x.sub?' · '+x.sub+' п/г':''}: ${esc(x.reason)}</p>`).join('')||(w.result.mode==='compact'?'<p>Уплотнение не назначает занятия из очереди. Для них используйте «Дополнить».</p>':'<p>Все выбранные готовые занятия распределены.</p>')}${w.result.removed.length?`<details><summary>Возвращаются в очередь</summary>${w.result.removed.map(a=>`<p>${esc(assignmentText(p,a))}</p>`).join('')}</details>`:''}<details><summary>Предупреждения (${w.result.warnings.length})</summary>${w.result.warnings.map(x=>`<p>${esc(p.groups.find(g=>g.id===x.group)?.code)}: ${esc(x.text)}</p>`).join('')}</details>${button('planner-apply','Применить вариант','primary')}${button('planner-back','Изменить условия')}`:`<p>Мастер использует только заданные допустимые слоты. Стремится уменьшить окна, число приездов и коротких дней, а также закрыть мигалки занятиями противоположной недели в те же часы. Для уже готового расписания выберите «Уплотнить готовое». Оптимальность и полное отсутствие окон не гарантируются.</p><fieldset><legend>Дни для расстановки</legend>${days.map((d,i)=>`<label class="inline"><input type="checkbox" name="planner-day" value="${i}" ${i===w.day?'checked':''}>${d}</label>`).join('')}</fieldset><label>Режим<select id="planner-mode"><option value="fill">Дополнить: сохранить все существующие назначения</option><option value="compact">Уплотнить готовое: сохранить дни и пары</option><option value="repair">Перерасставить выбранные дни: сохранить закреплённые группы</option></select></label><label>Группа<select id="planner-group"><option value="">Все группы</option>${p.groups.map(g=>`<option value="${esc(g.id)}">${esc(g.code)}</option>`).join('')}</select></label><label>Группы преподавателя<select id="planner-teacher"><option value="">Без ограничения</option>${p.teachers.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></label><label>Время поиска<select id="planner-time-limit"><option value="4000">4 секунды</option><option value="15000" selected>15 секунд</option><option value="30000">30 секунд</option></select></label><label>Желательно не более дней в неделю<input id="planner-days-limit" type="number" min="1" max="6" value="4"></label><label class="inline"><input id="planner-target" type="checkbox" checked>Не превышать заданную норму нагрузки</label><p>Закрепление любого занятия защищает всю группу от перерасстановки. Пустая норма не ограничивает нагрузку. Аудитории подбираются по вместимости; нехватка оставляет пометку.</p>${button('planner-run','Рассчитать вариант','planner-launch')}`}${w.error?`<p class="error">${esc(w.error)}</p>`:''}${button('planner-close',w.busy?'Отменить расчёт':'Закрыть')}</section></div>`}
export function changesView(p,r){if(!r)return '';return `<div class="modal-shade"><section class="planner-dialog" role="dialog" aria-modal="true" aria-label="Проверка изменений"><h2>${esc(r.label)}</h2><p>Перенесено или изменено: ${r.changed.length}; вернётся в очередь: ${r.removed.length}. Остальные назначения сохраняются.</p>${(r.cards||[]).map(x=>`<p><b>${esc(x.label)}</b>: ${esc(x.text)}</p>`).join('')}${r.locked?`<p class="warning">Затронуты закреплённые назначения: ${r.locked}. Применение разрешит эти изменения.</p>`:''}${r.changed.map(a=>`<p>${esc(assignmentText(r.project,a))}</p>`).join('')}${r.removed.map(a=>`<p class="warning">В очередь: ${esc(assignmentText(p,a))}</p>`).join('')}<details><summary>Предупреждения (${r.warnings.length})</summary>${r.warnings.map(w=>`<p>${esc(w.text)}</p>`).join('')}</details>${button('changes-apply','Применить изменения','primary')}${button('changes-close','Отмена')}</section></div>`}
function freeTimes(p,a){const g=p.groups.find(g=>g.id===a.group);if(!g.umu?.occupancy)return '<p class="warning">Полное расписание УМУ не загружено: проверьте занятость группы вручную.</p>';const bundle=slotBundle(g,a.slot,a);const available=days.flatMap((_,day)=>Array.from({length:7},(_,i)=>({day,pair:i+1}))).filter(dest=>bundle.every(o=>{const pair=o.pair+dest.pair-a.pair,week=g.slots.find(s=>s.id===o.slot).week;return pair>=1&&pair<=7&&!g.umu.occupancy.some(b=>!b.foreign&&!b.temporary&&intersects({day:dest.day,pair,week},b))&&!p.assignments.some(b=>b.group===g.id&&!bundle.some(o=>o.slot===b.slot)&&intersects({day:dest.day,pair,week},b))}));return `<label>Свободное время группы по исходному УМУ<select id="move-free"><option value="">Выбрать подсказку</option>${available.map(o=>`<option value="${o.day}:${o.pair}">${days[o.day]} · ${o.pair} пара</option>`).join('')}</select></label><small>Подсказки учитывают весь блок, но требуют проверки актуальности УМУ и согласования переноса.</small>`}
export function moveView(p,id){const a=p.assignments.find(a=>a.id===id);if(!a)return '';return `<div class="modal-shade"><section class="planner-dialog" role="dialog" aria-modal="true" aria-label="Перенос занятия"><h2>Перенос занятия</h2><p>${esc(assignmentText(p,a))}</p><p>Блок пар и обе подгруппы переносятся вместе. Замена преподавателя относится к выбранной подгруппе блока.</p>${freeTimes(p,a)}<label>День<select id="move-day">${days.map((d,i)=>`<option value="${i}" ${i===a.day?'selected':''}>${d}</option>`).join('')}</select></label><label>Номер выбранной пары<input id="move-pair" type="number" min="1" max="7" value="${a.pair}"></label><label>Преподаватель<select id="move-teacher">${p.teachers.map(t=>`<option value="${esc(t.id)}" ${t.id===a.teacher?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label class="inline"><input id="move-approved" type="checkbox">Перенос за пределы допустимых слотов согласован с УМУ</label>${button('move-preview','Проверить перенос','primary')}${button('move-close','Отмена')}</section></div>`}
